<template><view :class="['app-page',{dark}]"><ui-header title="订单列表" back/><scroll-view class="tabs" scroll-x :show-scrollbar="false"><view class="tab-row"><view v-for="item in tabs" :key="item.key" :class="['tab',{active:status===item.key}]" @tap="changeStatus(item.key)">{{item.label}}</view></view></scroll-view><view v-if="filtered.length" class="orders"><ui-order-card v-for="item in filtered" :key="item.id" :order="item" @select="detail(item)"><template #actions><view v-if="item.status==='unpaid'" class="order-action" @tap.stop="cancel(item)">取消订单</view><view v-if="item.status==='unpaid'" class="order-action primary" @tap.stop="pay(item)">继续支付</view><view v-if="['pending','accepted','serving','completed'].includes(item.status)" class="order-action" @tap.stop="afterSale(item)">申请售后</view><view v-if="item.status==='serving'&&item.providerCompletedAt" class="order-action primary" @tap.stop="confirmComplete(item)">确认完成</view><view v-if="item.canReview&&!item.reviewed" class="order-action primary" @tap.stop="openReview(item)">立即评价</view></template></ui-order-card></view><ui-page-status v-else :loading="loading" title="您还没有相关的订单" :description="error" @retry="load"/><view v-if="reviewDialog" class="sheet-mask" @tap="!reviewSubmitting&&(reviewDialog=false)"><view class="review-sheet" @tap.stop><text class="section-title">评价本次服务</text><view class="stars"><view v-for="n in 5" :key="n" :class="{on:n<=reviewForm.rating}" @tap="reviewForm.rating=n"><text :style="{color:n<=reviewForm.rating?'#ffad2f':'#cbd5e1',fontSize:'42rpx'}">{{n<=reviewForm.rating?'★':'☆'}}</text></view></view><text class="muted">当前评分：{{reviewForm.rating}} 星</text><textarea v-model="reviewForm.content" maxlength="500" placeholder="请填写真实的服务体验"/><text v-if="reviewError" class="error">{{reviewError}}</text><view class="primary-btn" @tap="submitReview">{{reviewSubmitting?'提交中…':'提交评价'}}</view></view></view></view></template>
<script>import{orderReview}from'@/services/order-review';import{api}from'@/services/api';import{isDark}from'@/utils/app';export default{mixins:[orderReview],data(){return{dark:false,status:'all',orders:[],loading:true,error:'',reviewDialog:false,reviewOrder:null,reviewError:'',reviewForm:{rating:5,content:''},tabs:[{key:'all',label:'全部'},{key:'unpaid',label:'待付款'},{key:'pending',label:'待接单'},{key:'accepted',label:'已接单'},{key:'serving',label:'服务中'},{key:'completed',label:'已完成'},{key:'review',label:'待评价'},{key:'aftersale',label:'退款/售后'}]}},computed:{filtered(){return this.orders}},onLoad(q){this.dark=isDark();this.status=q.status||'all'},onShow(){this.load()},methods:{changeStatus(key){this.status=key;this.load()},async load(){this.loading=true;this.error='';try{this.orders=await api.getOrders(this.status)}catch(e){this.orders=[];this.error=e.message||'订单加载失败'}finally{this.loading=false}},detail(item){uni.navigateTo({url:'/pages/order/detail?id='+item.id})},pay(item){uni.navigateTo({url:'/pages/order/payment?id='+item.id})},afterSale(item){uni.navigateTo({url:'/pages/aftersale/detail?orderId='+item.id})},async cancel(item){try{await api.cancelOrder(item.id);this.load()}catch(e){uni.showToast({title:e.message||'取消失败',icon:'none'})}},async confirmComplete(item){try{await api.confirmOrder(item.id);this.load()}catch(e){uni.showToast({title:e.message||'确认失败',icon:'none'})}}}}</script>
<style scoped>.tabs{position:relative;z-index:10;white-space:nowrap;background:var(--surface);border-top:1rpx solid var(--line)}.tab-row{display:inline-flex;min-width:100%;padding:0 10rpx}.tab{flex:0 0 auto;min-width:116rpx;height:82rpx;padding:0 14rpx;display:flex;align-items:center;justify-content:center;color:var(--muted);border-bottom:5rpx solid transparent;font-size:25rpx}.tab.active{color:var(--primary);border-color:var(--primary);font-weight:700}.orders{padding:20rpx 24rpx}.order-action{padding:12rpx 24rpx;border:1rpx solid var(--line);border-radius:30rpx;color:var(--text-secondary);font-size:24rpx}.order-action.primary{border-color:var(--primary);color:var(--primary)}.sheet-mask{position:fixed;z-index:200;inset:0;display:flex;align-items:flex-end;background:rgba(0,0,0,.55)}.review-sheet{width:100%;padding:34rpx 30rpx calc(30rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:var(--surface)}.stars{display:flex;justify-content:center;gap:12rpx;margin:28rpx}.stars>view{opacity:.25}.stars .on{opacity:1;color:#ffad2f}.review-sheet textarea{box-sizing:border-box;width:100%;height:190rpx;padding:22rpx;border-radius:18rpx;background:var(--surface-soft);color:var(--text)}.review-sheet .primary-btn{margin-top:26rpx}.error{display:block;margin:12rpx;color:var(--primary);font-size:22rpx}</style>
